import { Link } from 'react-router-dom';
import { useState } from 'react';
import { useAuth } from '../context/AuthContext';
import api, { API_URL } from '../api';

function timeAgo(date) {
  const d = new Date(date);
  const now = new Date();
  const diff = Math.floor((now - d) / 1000);
  if (diff < 60) return 'just now';
  if (diff < 3600) return `${Math.floor(diff/60)} min ago`;
  if (diff < 86400) return `${Math.floor(diff/3600)}h ago`;
  if (diff < 2592000) return `${Math.floor(diff/86400)}d ago`;
  return d.toLocaleDateString('en-US', { month: 'short', day: 'numeric' });
}

const css = `
  .postcard { padding: 24px 0; border-bottom: 1px solid #f2f2f2; width: 100%; box-sizing: border-box; }
  .postcard-body { display: flex; flex-direction: row; gap: 16px; margin-bottom: 12px; align-items: flex-start; width: 100%; min-width: 0; box-sizing: border-box; }
  .postcard-text { flex: 1 1 0%; min-width: 0; overflow: hidden; }
  .postcard-title { font-family: Lora, serif; font-weight: 700; color: #242424; line-height: 1.3; margin-bottom: 6px; word-break: break-word; white-space: normal; font-size: 18px; }
  .postcard-subtitle { font-size: 14px; color: #6b6b6b; line-height: 1.55; word-break: break-word; }
  .postcard-imgwrap { flex-shrink: 0; width: 160px; height: 104px; overflow: hidden; border-radius: 2px; display: block; }
  .postcard-img { width: 160px; height: 104px; object-fit: cover; display: block; }

  @media (max-width: 768px) {
    .postcard { padding: 16px 0; }
    .postcard-body { gap: 12px; }
    .postcard-title { font-size: 15px !important; line-height: 1.3; }
    .postcard-subtitle { display: none; }
    .postcard-imgwrap { width: 96px !important; height: 72px !important; flex-shrink: 0 !important; }
    .postcard-img { width: 96px !important; height: 72px !important; }
  }

  @media (max-width: 480px) {
    .postcard { padding: 14px 0; }
    .postcard-body { gap: 10px; }
    .postcard-title { font-size: 14px !important; line-height: 1.35; }
    .postcard-imgwrap { width: 80px !important; height: 64px !important; }
    .postcard-img { width: 80px !important; height: 64px !important; }
  }
`;

export default function PostCard({ post, size = 'md', showImage = true }) {
  const { user } = useAuth();
  const [bookmarked, setBookmarked] = useState(false);
  const [imgFailed, setImgFailed] = useState(false);

  const handleBookmark = async (e) => {
    e.preventDefault();
    if (!user) return;
    try {
      const { data } = await api.post(`/posts/${post._id}/bookmark`);
      setBookmarked(data.bookmarked);
    } catch {}
  };

  const imgUrl = post.coverImage
    ? post.coverImage.startsWith('http')
      ? post.coverImage
      : `${API_URL}${post.coverImage}`
    : null;

  const showImg = showImage && imgUrl && !imgFailed;

  return (
    <article className="postcard">
      <style>{css}</style>

      {/* Author row */}
      <div style={{ display: 'flex', alignItems: 'center', gap: 8, marginBottom: 12, minWidth: 0 }}>
        <Link to={`/profile/${post.author?._id}`} style={{ display: 'flex', alignItems: 'center', gap: 8, minWidth: 0 }}>
          <div style={{ width: 24, height: 24, borderRadius: '50%', background: '#242424', fontSize: 11, fontWeight: 700, color: '#fff', display: 'flex', alignItems: 'center', justifyContent: 'center', flexShrink: 0 }}>
            {post.author?.name?.[0]?.toUpperCase() || 'A'}
          </div>
          <span style={{ fontSize: 13, fontWeight: 500, color: '#242424', overflow: 'hidden', textOverflow: 'ellipsis', whiteSpace: 'nowrap' }}>{post.author?.name || 'Anonymous'}</span>
        </Link>
        <span style={{ fontSize: 13, color: '#9b9b9b', flexShrink: 0 }}>·</span>
        <span style={{ fontSize: 13, color: '#6b6b6b', flexShrink: 0 }}>{timeAgo(post.createdAt)}</span>
      </div>

      {/* Body */}
      <div className="postcard-body" style={size === 'lg' ? { flexDirection: 'column' } : {}}>
        <div className="postcard-text">
          <Link to={`/post/${post._id}`}>
            <h2 className="postcard-title" style={size === 'lg' ? { fontSize: 22 } : {}}>{post.title}</h2>
            {post.subtitle && (
              <p className="postcard-subtitle">
                {post.subtitle.slice(0, size === 'lg' ? 160 : 100)}{post.subtitle.length > 100 ? '...' : ''}
              </p>
            )}
          </Link>
        </div>

        {showImg && (
          <Link
            to={`/post/${post._id}`}
            className="postcard-imgwrap"
            style={size === 'lg' ? { width: '100%', height: 200 } : {}}
          >
            <img
              src={imgUrl}
              alt={post.title}
              className="postcard-img"
              style={size === 'lg' ? { width: '100%', height: 200 } : {}}
              onError={() => setImgFailed(true)}
            />
          </Link>
        )}
      </div>

      {/* Footer */}
      <div style={{ display: 'flex', justifyContent: 'space-between', alignItems: 'center', minWidth: 0 }}>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, minWidth: 0 }}>
          {post.category && (
            <Link to={`/tag/${post.category.toLowerCase()}`}
              style={{ display: 'inline-block', padding: '4px 10px', borderRadius: 999, background: '#f2f2f2', fontSize: 12, fontWeight: 500, color: '#242424', flexShrink: 0 }}>
              {post.category}
            </Link>
          )}
          <span style={{ fontSize: 13, color: '#6b6b6b', flexShrink: 0 }}>{post.readTime || 1} min read</span>
        </div>
        <div style={{ display: 'flex', alignItems: 'center', gap: 8, flexShrink: 0 }}>
          <span style={{ display: 'flex', alignItems: 'center', gap: 4, fontSize: 13, color: '#6b6b6b' }}>
            <svg width="16" height="16" viewBox="0 0 24 24" fill="none" stroke="#6b6b6b" strokeWidth="2"><path d="M14.5 10c-.83 0-1.5-.67-1.5-1.5v-5c0-.83.67-1.5 1.5-1.5s1.5.67 1.5 1.5v5c0 .83-.67 1.5-1.5 1.5z"/><path d="M20.5 10H19V8.5c0-.83.67-1.5 1.5-1.5s1.5.67 1.5 1.5-.67 1.5-1.5 1.5z"/><path d="M9.5 14.5v-10c0-.83.67-1.5 1.5-1.5s1.5.67 1.5 1.5v10"/><path d="M8.5 12.5H7V8.5C7 7.67 7.67 7 8.5 7S10 7.67 10 8.5"/><path d="M5 12.5c0-.83.67-1.5 1.5-1.5s1.5.67 1.5 1.5v1.5"/><path d="M4.5 20.5c1.5 1.5 3.5 2.5 5.5 2.5h4c3.31 0 6-2.69 6-6V13"/></svg>
            {post.claps || 0}
          </span>
          {user && (
            <button onClick={handleBookmark} style={{ display: 'flex', alignItems: 'center', padding: 4, background: 'none', border: 'none', cursor: 'pointer', color: bookmarked ? '#242424' : '#9b9b9b' }}>
              <svg width="16" height="16" viewBox="0 0 24 24" fill={bookmarked ? 'currentColor' : 'none'} stroke="currentColor" strokeWidth="2"><path d="m19 21-7-5-7 5V5a2 2 0 0 1 2-2h10a2 2 0 0 1 2 2z"/></svg>
            </button>
          )}
        </div>
      </div>
    </article>
  );
}
